/// <summary>
/// Extension class of <c>SalesTable</c> table
/// </summary>
[ExtensionOf(tableStr(SalesTable))]
public final class METSalesTable_Extension
{

}

Method.Source:
/// <summary>
/// Returns the record for <c>METSalesTable</c> table 
/// </summary>
/// <returns><c>METSalesTable</c> Table record</returns>
public METSalesTable metSalesTable()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METSalesTable));
}

    /// <summary>
    /// Pack the SalesTable extension table
    /// </summary>
    /// <param name = "_metSalesTable">METSalesTable to pack</param>
    public void metPackMETSalesTable(METSalesTable _metSalesTable)
    {
        _metSalesTable.SalesTable = this.RecId;

        this.SysExtensionSerializerMap::packExtensionTable(_metSalesTable);

    }

    /// <summary>
    /// Inserts a table buffer into the database.
    /// </summary>
    /// <param name = "_skipMarkup">Skip markup</param>
    public void insert(boolean _skipMarkup)
    {
        //NS-Added for the Task 122004: CB274 - Intercompany Transfers
        if (this.InterCompanyOrigin == InterCompanyOrigin::Derived && this.InterCompanyOriginalSalesId)
        {
            UnitIDBase                  unitID;
            METRoute                    routeId;
            METRouteStopNum             routeStop;
            SalesShippingDateConfirmed  shippingDate;

            changecompany(VendParameters::find().METInterCompanyLegalEntity)
            {
                routeId         = SalesTable::find(this.InterCompanyOriginalSalesId).METRoute;
                routestop       = SalesTable::find(this.InterCompanyOriginalSalesId).METRouteStopNum;
                shippingDate    = SalesTable::find(this.InterCompanyOriginalSalesId).ShippingDateConfirmed;

            }

            this.METRoute               = routeId;
            this.METRouteStopNum        = routestop;
            this.ShippingDateConfirmed  = shippingDate;
        }
        //NE-Added for the Task 122004: CB274 - Intercompany Transfers

        METSalesTable metSalesTable;

        next insert(_skipMarkup);

        metSalesTable = this.metSalesTable();
        metSalesTable.IndustryKey = METCustTable::find(this.CustAccount).IndustryKey;

        if (metSalesTable.RecId == 0)
        {
            this.metPackMETSalesTable(metSalesTable);
            this.SysExtensionSerializerMap::postInsert();
        }
    }

    /// <summary>
    /// Updates a table buffer into the database.
    /// </summary>
    public void update()
    {
        SalesTable  salesTableOrig = this.orig();

        if (salesTableOrig.METIOMSyncComplete == NoYes::No && this.METIOMSyncComplete == NoYes::Yes)
        {
            this.METUpdateEventOrderFields();
        }

        next update();

        this.SysExtensionSerializerMap::postUpdate();

        //CB616_TMSEngineSOCancellation
        //TMS Engin SO Cancellation processing
        if (salesTableOrig.SalesStatus != SalesStatus::Canceled && this.SalesStatus == SalesStatus::Canceled)
        {
            METTMSEngineSalesOrderProccess  metTMSEngineSalesOrderProccess = METTMSEngineSalesOrderProccess::construct(METTMSEngineSalesOrderProcess::Cancellation);
            metTMSEngineSalesOrderProccess.init(this);
            metTMSEngineSalesOrderProccess.run();
        }

    }

    /// <summary>
    /// Updates extract status.
    /// </summary>
    void  metUpdateExtractStatus()
    {
        SalesTableType  salesTableType;

        salesTableType = this.type();
        salesTableType.metUpdateExtractStatus();
    }

/// <summary>
/// CB166_SalesOrderSubstitutes
/// Step 1: Check substitution applies for the order’s Metcash Sales Order Type
/// </summary>
/// <returns>True if substitution allowed; otherwise, false.</returns>
public boolean METSubstitutesAllowed()
{        
    return METSalesOrderTypes::find(this.METSalesOrderType).SubstitutesAllowed;
}

    /// <summary>
    /// MPJ_28155_SalesFinalisation 3.6.3 Sales order shipments
    /// Check if there is a released product with hazardous material in the sales order where the line status is not cancelled
    /// </summary>
    /// <param name = "_salesId">sales id</param>
    /// <returns>True if there is a released product hazardous material; otherwise, false</returns>
    static boolean METexistHazardousMaterial(SalesId _salesId)
    {
        SalesLine   salesLine;
        InventTable inventTable;
        if (!_salesId)
        {
            return false;
        }

        select firstonly RecId from SalesLine
                exists join InventTable
                    where SalesLine.SalesId == _salesId
                       && SalesLine.ItemId == InventTable.ItemId
                       // exclude lines that are cancelled
                       && SalesLine.SalesStatus != SalesStatus::Canceled
                       && InventTable.HMIMIndicator == NoYes::Yes;

        return SalesLine.RecId != 0;
    }

    /// <summary>
    /// MPJ_28155_SalesFinalisation 3.7.2 Periodic task
    /// Check if there is a sales order for the same customer and route that is not picked
    /// </summary>
    /// <param name = "_salesId">sales id</param>
    /// <param name = "_custAccount">Customer account</param>
    /// <param name = "_route">route</param>
    /// <returns>True if there is a sales order not picked for same customer and route; otherwise, false</returns>
    static boolean METexistSalesOrderNotPicked(SalesId _salesId, CustAccount _custAccount, METRoute _route)
    {
        SalesTable   salesTable;
        WMSPickingRoute wmsPickingRoute;
        if (!_salesId || !_custAccount || !_route)
        {
            return false;
        }

        // a SO with a picking list not completed (no picking registration)
        select firstonly RecId from salesTable
                    where salesTable.SalesStatus == SalesStatus::Backorder
                       && salesTable.SalesType == SalesType::Sales
                       && salesTable.SalesId != _salesId
                       && salesTable.CustAccount == _custAccount
                       && salesTable.METRoute == _route
              exists join wmsPickingRoute
                    where wmsPickingRoute.transRefId == salesTable.SalesId
                       && wmsPickingRoute.transType == InventTransType::Sales
                       && wmsPickingRoute.expeditionStatus !=  WMSExpeditionStatus::Complete;

        return (salesTable.RecId != 0);
    }

    /// <summary>
    /// MPJ-37929 Transfer Order and Sales Order Finalisation - 3.6.2 Sales order shipment workbench changes
    /// Check if there is a sales order for the same customer and route that is not picked
    /// </summary>
    /// <param name = "_salesId">sales id</param>
    /// <param name = "_custAccount">Customer account</param>
    /// <param name = "_route">route</param>
    /// <returns>True if there is a sales order not picked for same customer and route; otherwise, false</returns>
    static boolean METSalesOrderNotPicked(SalesId _salesId, CustAccount _custAccount, METRoute _route)
    {
        SalesTable   salesTable;
        WMSPickingRoute wmsPickingRoute;
        if (!_salesId || !_custAccount || !_route)
        {
            return false;
        }

        // a SO with a picking list not completed (no picking registration)
        select firstonly RecId from salesTable
                    where salesTable.SalesType == SalesType::Sales
                       && salesTable.SalesId == _salesId
                       && salesTable.CustAccount == _custAccount
                       && salesTable.METRoute == _route
              exists join wmsPickingRoute
                    where wmsPickingRoute.transRefId == salesTable.SalesId
                       && wmsPickingRoute.transType == InventTransType::Sales
                       && wmsPickingRoute.expeditionStatus !=  WMSExpeditionStatus::Complete;

        return (salesTable.RecId != 0);
    }

    /// <summary>
    /// Validate if Sales order excluded from TMS engine
    /// </summary>
    /// <returns>
    /// a boolean value<c>boolean</c> query.
    /// </returns>
    public boolean METIsSalesOrderExcluded()
    {
        METSalesOrderTypes  salesOrderTypes;
        boolean             ret = false;

        salesOrderTypes = METSalesOrderTypes::find(this.METSalesOrderType);
        if (salesOrderTypes.RecId)
        {
            ret = salesOrderTypes.ExcludeFromTMSEngine;
        }

        return ret;
    }

/// <summary>
/// Validate if Sales order is Perishable
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
public boolean METIsSalesOrderPerishable()
{
    InventParameters    inventParameters = InventParameters::find();
    boolean             ret = false;
    if (inventParameters.METPerishableOrderSplitGroup)
    {
        ret = this.metSalesTable().OrderSplitGroup == inventParameters.METPerishableOrderSplitGroup;
    }
    return ret;
}

/// <summary>
/// CB166_SalesOrderSubstitutes
/// Method to retrieve METSalesOrderTypes from SalesTable
/// </summary>
/// <param name = "_forUpdate">Select <c>METSalesOrderTypes</c> for update.</param>
/// <returns><c>METSalesOrderTypes</c> record</returns>
public METSalesOrderTypes METSalesOrderTypes(boolean _forUpdate = false)
{
    return METSalesOrderTypes::find(this.METSalesOrderType, _forUpdate);
}

    /// <summary>
    /// CB167_PerformStockReservation.
    /// Checks for event otder.
    /// </summary>
    /// <returns>True, if event order; otherwise; false.</returns>
    public boolean METIsEventOrder()
    {
        METSalesTable metSalesTable = this.metSalesTable();

        return (metSalesTable.EventID != '');
    }

    /// <summary>
    /// CB167_PerformStockReservation.
    /// Updates event order fields.
    /// </summary>
    private void METUpdateEventOrderFields()
    {
        METSalesTable metSalesTable = this.metSalesTable();

        if (metSalesTable && metSalesTable.ExtendedTerms)
        {
            if (metSalesTable.ExtendedTermsMethod == METExtendedTermsMethod::InvoiceDueDate)
            {
                this.FixedDueDate = metSalesTable.ExtendedDate;
            }
            else if (metSalesTable.ExtendedTermsMethod == METExtendedTermsMethod::ExtendedDays)
            {
                utcdatetime convertedDateTime = DateTimeUtil::newDateTime(this.FixedDueDate, 0, DateTimeUtil::getUserPreferredTimeZone());
                convertedDateTime = DateTimeUtil::addDays(convertedDateTime, metSalesTable.ExtendedDays);

                this.FixedDueDate = DateTimeUtil::date(convertedDateTime);
            }

        }
    }

/// <summary>
