}

/// <summary>
/// Method to get last pick list generated for sales order
/// </summary>
/// <param name = "_salesId">SalesId reference</param>
/// <returns>WMSPickingRoute</returns>
public static WMSPickingRoute getLastPickListInfo(SalesId       _salesId)
{
    WMSPickingRoute     wmsPickingRoute;
    WMSOrderTrans       wmsOrderTrans;
    SalesLine           salesLine;
        
    select firstonly pickingRouteID, CreatedDateTime, CreatedBy from wmsPickingRoute
        order by CreatedDateTime desc
            exists join wmsOrderTrans
                where wmsOrderTrans.routeId == wmsPickingRoute.pickingRouteID
            exists join salesLine
                where salesLine.InventTransId == wmsOrderTrans.inventTransId &&
                    salesLine.SalesId == _salesId;
                
    return wmsPickingRoute;
}

    /// CB123 - SalesOrderExtractScreenforCSD
    /// <summary>
    /// Create wave for the sales order
    /// </summary>
    /// <param name = "_isPickDirector">Is Pick director.</param>
    /// <param name = "_csdSalesOrderCount">Csd sales order count for extraction</param>
    public void createWaveFromSalesTable(boolean _isPickDirector = false, RefRecId _csdSalesOrderCount = 0)
    {
        #OCCRetryCount

        try
        {
            
            METWaveTable waveTable;
            boolean      waveLinesInserted = false;
            RecordInsertList waveLineInsertList = new RecordInsertList(tableNum(METWaveLine));

            try
            {
                ttsbegin;

                if (!METWaveTable::existByWarehouseOrderExtractDateTime(this.InventLocationId,
                                                                        this.METOrderExtractDateTime))
                {
                    waveTable.clear();
                    waveTable.initValue();
                    waveTable.Warehouse      = this.InventLocationId;
                    waveTable.Site           = this.InventSiteId;
                    waveTable.generateWaveId(this.METOrderExtractDateTime);
                    waveTable.OrderExtractDateTime = this.METOrderExtractDateTime;
                        
                    if (waveTable.validateWrite())
                    {
                        waveTable.insert();
                    }
                }
                ttscommit;

                if (waveTable)
                {
                    try
                    {
                        if (METWaveTable::existWaveNumWithZeroForInventLocationId(this.InventLocationId, waveTable.CreatedDateTime))
                        {
                            ttsbegin;
                            waveTable.selectForUpdate(true);
                            waveTable.WaveNumber = METWaveTable::getWaveNum(waveTable.Warehouse, waveTable.CreatedDateTime);
                            waveTable.Update();
                            ttscommit;
                        }
                    }
                    catch (Exception::Deadlock)
                    {
                        retry;
                    }
                    catch (Exception::DuplicateKeyException)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            throw Exception::UpdateConflictNotRecovered;
                        }
                        else
                        {
                            retry;
                        }
                    }
                    catch (Exception::UpdateConflict)
                    {
                        if (appl.ttsLevel() == 0)
                        {
                            if (xSession::currentRetryCount() >= #RetryNum)
                            {
                                throw Exception::UpdateConflictNotRecovered;
                            }
                            else
                            {
                                retry;
                            }
                        }
                        else
                        {
                            throw Exception::UpdateConflict;
                        }
                    }
                    catch (Exception::Error)
                    {
                        throw error("@SYS93835");
                    }
                        
                }
            }
            catch (Exception::Deadlock)
            {
                retry;
            }
            catch (Exception::DuplicateKeyException)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
            catch (Exception::Error)
            {
                throw error("@SYS93835");
            }

            if (waveTable || METWaveTable::existByOrderExtractDateTime(this.METOrderExtractDateTime))
            {
                METWaveLine      waveLine, metWaveLine;
                SalesLine        salesLine;
                    
                if (!waveTable)
                {
                    select firstonly OrderExtractDateTime, WaveId from waveTable
                        where waveTable.OrderExtractDateTime == this.METOrderExtractDateTime;
                }

                while select LineNum, SalesId, RecId from salesline
                    where salesLine.SalesId == this.SalesId
                    notexists join metWaveLine
                    where metWaveLine.DocNumRefRecId == salesLine.RecId
                {
                    waveLine.clear();
                    waveLine.LineNumber     = salesLine.LineNum;
                    waveLine.DocumentNumber = salesLine.SalesId;
                    waveLine.WaveId         = waveTable.WaveId;
                    waveLine.Type           = METType::SalesOrder;
                    waveLine.DocNumRefRecId = salesLine.RecId;
                    waveLine.OrderExtractDateTime = waveTable.OrderExtractDateTime;

                    if (waveLine.validateWrite())
                    {
                        waveLineInsertList.add(waveLine);
                        waveLinesInserted = true;
                    }
                }
            }

            if (waveLinesInserted)
            {
                ttsbegin;
                waveLineInsertList.insertDatabase();
                ttscommit;

                if (_isPickDirector && _csdSalesOrderCount > 0)
                {
                    METWaveLineCountView waveLineCountView;

                    select count(RecId) from waveLineCountView
                        where waveLineCountView.OrderExtractDateTime == waveTable.OrderExtractDateTime;

                    if (waveLineCountView.RecId == _csdSalesOrderCount)
                    {
                        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METSalesOrderWaveGeneratedBusinessEvent)))
                        {
                            METSalesOrderWaveGeneratedBusinessEvent::newFromSalesWave(waveTable.WaveId).send();
                        }
                    }
                }
            }
        }
        catch
        {
            error ("@WAX:UpdateCancelled");
        }
    }

    /// <summary>
    /// Copy of unlinkAgreement to remove the if statement as salesTable.MatchingAgreement will not be set for quotas
    /// </summary>
    /// <param name = "_unlinkLines"></param>
    /// <param name = "_recalculatePrice"></param>
    /// <param name = "_doUpdateSalesLine"></param>
    public void METUnlinkAgreement(boolean _unlinkLines           = true,
                                   boolean _recalculatePrice      = false,
                                   boolean _doUpdateSalesLine     = true)
    {
        AgreementReleaseHeaderMatch agreementReleaseHeaderMatch;
        SalesLine                   salesLine;
        boolean                     restorePriceDiscChagnePolicy = true;
        SalesTable_RU               salesTableRU;

        #ISOCountryRegionCodes

        if (this.metSalesTable().LinkedSalesAgreement)
        {
            ttsbegin;

            if (_unlinkLines)
            {
                while select forupdate salesLine
                        where salesLine.SalesId == this.SalesId
                {
                    this.unlinkAgreementOnSalesLine(salesLine, _recalculatePrice, _doUpdateSalesLine);
                }
            }

            delete_from agreementReleaseHeaderMatch
            where agreementReleaseHeaderMatch.SalesTableSalesId == this.SalesId
                && agreementReleaseHeaderMatch.SalesTableDataAreaId == this.DataAreaId;

            ttscommit;
        }
    }

/// <summary>
/// When the quota process runs multiple times, the method is to uncancel lines that were cancelled by quota process
/// </summary>
public void METUncancelQuotaLines()
{
    SalesLine    SalesLine;
    METSalesLine METSalesLine;
    
    if (this.metSalesTable().LinkedSalesAgreement)
    {
        while select salesLine
         exists join METSalesLine
               where salesLine.SalesId == this.SalesId
                  && salesLine.SalesStatus == SalesStatus::Canceled
                  && METSalesLine.SalesLine == salesLine.RecId
                  && METSalesLine.OrderedQuantity != 0
                  && METSalesLine.ReasonId != ''
        {
            InventQty salesLineInventQty = salesLine.calcQtyOrdered();
            
            salesLine.metUpdateDeliverRemainder(salesLine.SalesQty, salesLineInventQty);
        }
    }
}
